{
  "findings": [
    {
      "check_id": "CKV_GCP_44",
      "title": "Google Compute Disk is not encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_compute_disk.changeme_count_attached_disk_disk",
      "severity": "MEDIUM",
      "explanation": "The disk is not encrypted with a Customer Supplied Encryption Key (CSEK), which could lead to data being encrypted with a key managed by Google, potentially reducing control over data encryption."
    }
  ],
  "patched_code": "resource \"google_compute_disk\" \"changeme_count_attached_disk_disk\" {\n  name                      = \"changeme-count-attached-disk-disk-${count.index}\"\n  count                     = var.changeme_google_attached_disk_count_number_of_instances\n  type                      = \"pd-ssd\"\n  zone                      = \"us-central1-a\"\n  size                      = 4\n  physical_block_size_bytes = 4096\n  disk_encryption_key {\n    raw_key = var.disk_encryption_key\n  }\n}",
  "fix_summary": "Added disk encryption key to the google_compute_disk resource to enable encryption with Customer Supplied Encryption Keys (CSEK)."
}
